import{_ as n,o as r,c as t,ai as i}from"./chunks/framework.BxxKhjs3.js";const a="/pub-blog/assets/image-20251127081035219.DD1TP58X.png",u=JSON.parse('{"title":"流碧卡片 6 小时闪电开发 AI gemini-3-pro-preview ！ 秒出小红书爆款图，免下载直接用","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/流碧卡片 6 小时闪电开发 AI gemini-3-pro-preview ！ 秒出小红书爆款图，免下载直接用/流碧卡片 6 小时闪电开发 AI gemini-3-pro-preview ！ 秒出小红书爆款图，免下载直接用.md","filePath":"AI人工智能/流碧卡片 6 小时闪电开发 AI gemini-3-pro-preview ！ 秒出小红书爆款图，免下载直接用/流碧卡片 6 小时闪电开发 AI gemini-3-pro-preview ！ 秒出小红书爆款图，免下载直接用.md","lastUpdated":1765296327000,"__rawMarkdown":"# 流碧卡片 6 小时闪电开发 AI gemini-3-pro-preview ！ 秒出小红书爆款图，免下载直接用\\n\\n> **体验地址**: [https://card.zbztb.cn](https://card.zbztb.cn)  \\n> **开发驱动**: Trae IDE + Gemini-3-pro-Preview\\n\\n---\\n\\n## 简介 | Introduction\\n\\n**流碧卡片 (Liubi Card)** 是一款专注于**优雅、高效、隐私**的社交媒体卡片生成工具。它可以将您的文字、代码或灵感瞬间转化为设计感十足的图片，完美适配微信、小红书、Instagram 等社交平台。\\n\\n本项目完全采用**纯前端技术栈**开发，由新一代 AI 编程 IDE **Trae** 搭载 **Gemini-3-pro-Preview** 模型辅助构建，展现了 AI 赋能开发的无限可能。\\n\\n![image-20251127081035219](assets/image-20251127081035219.png)\\n\\n---\\n\\n##  核心亮点 | Key Features\\n\\n### 1. 海量风格模板 (40+ Built-in Templates)\\n从**赛博朋克**的霓虹幻彩，到**莫兰迪**的温柔静谧；从**水彩**的艺术质感，到**极简**的商务风格。\\n我们内置了超过 **40 种**精心设计的视觉模板，一键切换，即刻出片。\\n- **最新新增**: 日落、森林、午夜、糖果、旧纸张、蓝图、终端等 20 款全新风格。\\n\\n### 2. 每日灵感 (Daily Inspiration)\\n每天首次访问，都会收到一份专属的惊喜。\\n- **智能随机**: 从精选的 100+ 条中英文金句中随机抽取。\\n- **风格碰撞**: 自动匹配一种独特的视觉风格，让每天的打卡都与众不同。\\n\\n### 3. AI 智能文案优化 (AI-Powered)\\n接入 **DeepSeek** 大模型能力，为您的一键润色文案。\\n- 让平淡的文字变得更有社交传播力。\\n- 自动提取金句，优化排版。\\n\\n### 4.  极致隐私安全 (Privacy First)\\n- **零后端依赖**: 所有图片生成、文字处理均在您的**浏览器本地**完成。\\n- **数据不上传**: 您的创作内容绝不会上传至任何服务器，安全无忧。\\n\\n### 5.  完美适配移动端 (Responsive Design)\\n- 专为手机和平板优化的交互体验。\\n- 支持 **3:4 (小红书)**、**9:16 (抖音)**、**1:1 (Instagram)** 等多种主流比例。\\n\\n---\\n\\n## 技术栈 | Tech Stack\\n\\n本项目是现代前端工程化的典范，使用了以下核心技术：\\n\\n- **核心框架**: React 19 + TypeScript\\n- **构建工具**: Vite 6\\n- **UI 系统**: Ant Design 6 + Tailwind CSS\\n- **国际化**: i18next (支持中英双语)\\n- **绘图引擎**: html2canvas\\n- **AI 辅助**: Trae IDE + Gemini-3-pro-Preview\\n\\n---\\n\\n##  开发背后的故事 | Development Story\\n\\n这个项目的快速迭代得益于 **Trae IDE** 与 **Gemini-3-pro-Preview** 的强大组合。\\n\\n### 高效的各种功能实现\\n在开发过程中，我只需通过自然语言描述需求：\\n> \\"帮我增加一个每日随机生成卡片功能，需要判断是否今日首次打开，并随机选择内容和风格...\\"\\n\\nGemini-3-pro-Preview 能够瞬间理解上下文：\\n1.  **自动规划**: 识别需要修改 `HomePage.tsx` 添加逻辑，创建 `quotes.ts` 存储语录。\\n2.  **代码生成**: 自动编写了完整的 `checkDailyCard` 逻辑和 `generateDailyCard` 函数。\\n3.  **Bug 修复**: 当遇到 React StrictMode 导致的弹窗重复问题时，AI 迅速给出了从“命令式”到“声明式”状态管理的重构方案。\\n\\n### 创意的批量生产\\n当需要新增 **20 种模板** 时，AI 不仅生成了代码，还为每个模板设计了独特的配色方案（渐变、阴影、边框），并同步完成了中英文的本地化配置，将原本需要数小时的重复工作压缩到了几分钟。\\n\\n---\\n\\n## 🔗 立即体验\\n\\n**点击访问**: [https://card.zbztb.cn](https://card.zbztb.cn)\\n\\n无论您是想记录生活感悟，还是分享技术代码，流碧卡片都能让您的文字更加闪耀。\\n\\n---\\n\\n"}'),o={name:"AI人工智能/流碧卡片 6 小时闪电开发 AI gemini-3-pro-preview ！ 秒出小红书爆款图，免下载直接用/流碧卡片 6 小时闪电开发 AI gemini-3-pro-preview ！ 秒出小红书爆款图，免下载直接用.md"};function s(l,e,p,g,c,d){return r(),t("div",null,[...e[0]||(e[0]=[i("",41)])])}const m=n(o,[["render",s]]);export{u as __pageData,m as default};
